}];

// Formatar Resposta da Alteração de Cliente
const resultado = $input.all();

// Verifica se o MySQL retornou algum registro
if (resultado.length === 0 || !resultado[0].json || Object.keys(resultado[0].json).length === 0) {
  // Cenário: Cliente não encontrado após atualização (erro inesperado)
  return [{
    json: {
      sucesso: false,
      mensagem: "Erro ao atualizar cliente. Tente novamente.",
      cliente: null
    }
  }];
}

// Cliente atualizado - pega o primeiro registro
const clienteData = resultado[0].json;

// Formata a resposta de sucesso
return [{
  json: {
    sucesso: true,
    mensagem: "Cliente atualizado com sucesso.",
    cliente: {
      id: clienteData.IdCliente,
