    }
  }
}];

// Resposta quando cliente não existe para alteração
return [{
  json: {
    sucesso: false,
    mensagem: "Cliente não encontrado para alteração.",
    cliente: null
  }
}];

// Decidir se cadastra ou retorna erro
const resultado = $input.all();

// Verifica se o SELECT retornou dados (email existe)
if (resultado.length > 0 && resultado[0].json && resultado[0].json.IdCliente) {
