    dadosOriginais = $('Direcionar Ação').item.json.dados;
  }

  // Se não encontrou, tenta do $json atual
  if (!dadosOriginais && $json && $json.dados) {
    dadosOriginais = $json.dados;
  }

  // Se ainda não encontrou, tenta do input
  if (!dadosOriginais && resultado[0] && resultado[0].json) {
    dadosOriginais = resultado[0].json.dados;
  }

  return [{
    json: {
      emailExiste: false,
      dadosCadastro: dadosOriginais
    }
  }];
}

const resultado = $input.all();

// =====================================================
// VALIDAÇÃO DO RETORNO DO MYSQL
// =====================================================

if (
  resultado.length === 0 ||
  !resultado[0].json ||
  Object.keys(resultado[0].json).length === 0
) {
  return [
    {
      json: {
        sucesso: false,
        acao: 'cadastrar_produto',
        mensagem: 'Erro ao cadastrar produto.',
        produto: null
      }
    }
  ];
}

// =====================================================
// PRODUTO ENCONTRADO
// =====================================================

const produto = resultado[0].json;

return [
  {
    json: {
      sucesso: true,
      acao: 'cadastrar_produto',
      mensagem: 'Produto cadastrado com sucesso.',
      produto: {
        IdProduto: produto.IdProduto,
        Nome: produto.Nome,
        Descricao: produto.Descricao,
        Preco: Number(produto.Preco),
        Estoque: produto.Estoque,
        Categoria: produto.Categoria,
        CodigoBarras: produto.CodigoBarras,
        SKU: produto.SKU,
        DataCadastro: produto.DataCadastro,
        Ativo: produto.Ativo
      }
    }
  }
];

