// Gerar um item do n8n para cada produto
return itens.map((item, index) => {
  const idProduto = Number(item.IdProduto);
  const quantidade = Number(item.Quantidade);

  if (!Number.isInteger(idProduto) || idProduto <= 0) {
    throw new Error(`IdProduto inválido no item ${index + 1}.`);
  }

  if (!Number.isInteger(quantidade) || quantidade <= 0) {
    throw new Error(`Quantidade inválida no item ${index + 1}.`);
  }

  return {
    json: {
      IdCliente: idCliente,
      IdProduto: idProduto,
      Quantidade: quantidade,
    },
  };
});

const produtos = $input.all().map(item => item.json);

// Recuperar a solicitação original da compra
const solicitacao = $('Validar e Preparar Compra').first().json;
const dados = solicitacao.dados ?? solicitacao;

const idCliente = Number(dados.IdCliente);
const itensSolicitados = dados.Itens ?? dados.itens ?? [];

const erros = [];

if (!Number.isInteger(idCliente) || idCliente <= 0) {
  erros.push('IdCliente ausente ou inválido.');
}

if (!Array.isArray(itensSolicitados) || itensSolicitados.length === 0) {
  erros.push('Nenhum item foi informado para a compra.');
}

if (erros.length > 0) {
  return [{
    json: {
      sucesso: false,
      acao: 'cadastrar_compra',
      mensagem: 'Não foi possível validar a compra.',
      erros
    }
  }];
}

// Normalizar os campos retornados pelo MySQL
const produtosNormalizados = produtos.map(p => ({
  IdProduto: Number(p.IdProduto ?? p.idProduto ?? p.id_produto),
  Nome: p.Nome ?? p.nome,
  Ativo: p.Ativo ?? p.ativo,
  Estoque: Number(p.Estoque ?? p.estoque),
  Preco: Number(p.Preco ?? p.preco ?? p.PrecoUnitario)
}));

const itensValidados = [];

for (const item of itensSolicitados) {
  const idProduto = Number(item.IdProduto);
  const quantidade = Number(item.Quantidade);

  const produto = produtosNormalizados.find(
    p => p.IdProduto === idProduto
  );

  if (!produto) {
    erros.push(
      `Produto ID ${idProduto} não encontrado na saída do MySQL. IDs retornados: ${
        produtosNormalizados.map(p => p.IdProduto).join(', ') || 'nenhum'
      }.`
    );
    continue;
  }

  if (Number(produto.Ativo) !== 1) {
    erros.push(`O produto "${produto.Nome}" está inativo.`);
    continue;
  }

  if (!Number.isInteger(quantidade) || quantidade <= 0) {
    erros.push(`Quantidade inválida para "${produto.Nome}".`);
    continue;
  }

  if (!Number.isFinite(produto.Estoque) || produto.Estoque < quantidade) {
    erros.push(
      `Estoque insuficiente ou inválido para "${produto.Nome}". Disponível: ${produto.Estoque}.`
    );
    continue;
  }

  if (!Number.isFinite(produto.Preco) || produto.Preco < 0) {
    erros.push(`Preço inválido para "${produto.Nome}".`);
    continue;
  }

  itensValidados.push({
    IdProduto: produto.IdProduto,
    Nome: produto.Nome,
    Quantidade: quantidade,
    PrecoUnitario: produto.Preco,
    Subtotal: Number((produto.Preco * quantidade).toFixed(2))
  });
}

if (erros.length > 0) {
  return [{
    json: {
      sucesso: false,
      acao: 'cadastrar_compra',
      mensagem: 'Não foi possível validar os produtos.',
      erros
    }
  }];
}

const valorTotal = Number(
  itensValidados.reduce((total, item) => total + item.Subtotal, 0).toFixed(2)
);

return [{
  json: {
    sucesso: true,
    acao: 'cadastrar_compra',
    IdCliente: idCliente,
    itens: itensValidados,
    ValorTotal: valorTotal
  }
}];

