    {{
        (() => {
            const entrada = $json;
            const idCliente = Number(
                entrada.IdCliente ?? entrada.dados?.IdCliente
            );

            if (
                !Number.isInteger(idCliente) ||
                idCliente <= 0
            ) {
                throw new Error(
                    'IdCliente ausente ou inválido. Confira a saída de Validar Produtos da Compra.'
                );
            }

            return idCliente;
        })()
    }},
    '{{
        (() => {
            const entrada = $json;
            const itens = entrada.itens ?? entrada.Itens ?? entrada.dados?.Itens;

            if (!Array.isArray(itens) || itens.length === 0) {
                throw new Error(
                    'Lista de itens ausente. Confira a saída de Validar Produtos da Compra.'
                );
            }

            const lista = itens.map((item, indice) => {
                const idProduto = Number(item.IdProduto);
                const quantidade = Number(item.Quantidade);

                if (
                    !Number.isInteger(idProduto) ||
                    idProduto <= 0 ||
                    !Number.isInteger(quantidade) ||
                    quantidade <= 0
                ) {
                    throw new Error(
                        `Item ${indice + 1}: IdProduto ou Quantidade inválidos.`
                    );
                }

                return {
                    IdProduto: idProduto,
                    Quantidade: quantidade
                };
            });

            return JSON.stringify(lista).replace(/'/g, "''");
        })()
    }}'
);

