const resultado = $input.first().json;

// Identificar erros retornados pelo nó MySQL
const mensagemErro =
  resultado.error?.message ||
  resultado.message ||
  resultado.description;

// Se o MySQL retornou um erro, responder sem afirmar que a compra foi registrada
if (
  resultado.error ||
  (mensagemErro && /unknown column|error|failed|invalid/i.test(mensagemErro))
) {
  return [{
    json: {
      sucesso: false,
      acao: 'cadastrar_compra',
      mensagem: 'Não foi possível registrar a compra. Verifique os dados e tente novamente.',
      erro: {
        mensagem: mensagemErro || 'Erro não especificado pelo banco de dados.'
      }
    }
  }];
}

// O CALL pode retornar os dados da procedure em um array
let dados = resultado;

if (Array.isArray(resultado)) {
  dados = resultado.find(item =>
    item &&
    typeof item === 'object' &&
    item.IdCompra !== undefined
  ) || resultado[0];
}

if (Array.isArray(dados)) {
  dados = dados.find(item =>
    item &&
    typeof item === 'object' &&
    item.IdCompra !== undefined
  ) || dados[0];
}

// Se não houver confirmação do banco, não afirmar sucesso
if (
  !dados ||
  typeof dados !== 'object' ||
  dados.IdCompra === undefined ||
  Number(dados.sucesso) !== 1
) {
  return [{
    json: {
      sucesso: false,
      acao: 'cadastrar_compra',
      mensagem: 'Não foi possível confirmar o registro da compra. Verifique o histórico antes de tentar novamente.'
    }
  }];
}

// Resposta de sucesso
return [{
  json: {
    sucesso: true,
    acao: 'cadastrar_compra',
    mensagem: dados.mensagem || 'Compra registrada com sucesso.',
    compra: {
      IdCompra: Number(dados.IdCompra),
      IdCliente: Number(dados.IdCliente),
      ValorTotal: Number(dados.ValorTotal),
      Status: dados.Status
    }
  }
}];

// Resposta quando cliente já existe
return [{
  json: {
    sucesso: false,
    mensagem: "Cliente já cadastrado com este email.",
    cliente: $json.clienteExistente
  }
}];

const dados = $('Validar e Preparar Requisição').item.json.dados;

const cliente = {
  IdCliente: dados.IdCliente
};

// Adiciona somente os campos que realmente foram informados
const campos = [
  'IdCliente',
    'Nome',
  'Email', 
  'Telefone',
  'DataCadastro',
  'Status'
];

for (const campo of campos) {
  const valor = dados[campo];

  if (
    valor !== null &&
    valor !== undefined &&
    String(valor).trim() !== ''
  ) {
    cliente[campo] = valor;
  }
}

return [
  {
    json: cliente
  }
];

// Resposta quando Produto já existe
return [{
  json: {
    sucesso: false,
    mensagem: "Já existe um produto cadastrado com este SKU.",
    produto: $json.produtoExistente
  }
}];

// Recupera todas as compras
const compras = $('Consultar Compras').all();

// Recupera todos os itens das compras
const itens = $input.all();

// Organiza os itens por compra
const comprasFormatadas = compras.map(item => {
  const compra = item.json;

  const itensDaCompra = itens
    .filter(registro =>
      Number(registro.json.IdCompra) === Number(compra.IdCompra)
    )
    .map(registro => ({
      IdItem: registro.json.IdItem,
      IdProduto: registro.json.IdProduto,
      NomeProduto: registro.json.NomeProduto,
      Quantidade: Number(registro.json.Quantidade),
      PrecoUnitario: Number(registro.json.PrecoUnitario)
    }));

  return {
    IdCompra: compra.IdCompra,
    IdCliente: compra.IdCliente,
    DataCompra: compra.DataCompra,
    ValorTotal: Number(compra.ValorTotal),
    Status: compra.Status,
    itens: itensDaCompra
  };
});

return [{
  json: {
    sucesso: true,
    acao: 'consultar_compra',
    compras: comprasFormatadas
  }
}];

const resultado = $input.first().json;

if (!resultado.sucesso) {
  return [{
    json: {
      sucesso: false,
      acao: 'consultar_compra',
      mensagem: 'Não foi possível consultar o histórico de compras.'
    }
  }];
}

if (!resultado.compras || resultado.compras.length === 0) {
  return [{
    json: {
      sucesso: true,
      acao: 'consultar_compra',
      mensagem: 'Este cliente ainda não possui compras registradas.',
      compras: []
    }
  }];
}

const compras = resultado.compras;

const historico = compras.map(compra => {
  const itens = compra.itens.map(item =>
    `${item.Quantidade}x ${item.NomeProduto} — R$ ${item.PrecoUnitario.toFixed(2).replace('.', ',')}`
  ).join('\n');

  return [
    `Compra #${compra.IdCompra}`,
    `Data: ${compra.DataCompra}`,
    `Status: ${compra.Status}`,
    `Valor total: R$ ${compra.ValorTotal.toFixed(2).replace('.', ',')}`,
    `Produtos:\n${itens}`
  ].join('\n');
}).join('\n\n');

return [{
  json: {
    sucesso: true,
    acao: 'consultar_compra',
    mensagem: `Histórico de compras encontrado:\n\n${historico}`,
    compras
  }
}];

return [{
  json: {
    sucesso: false,
    acao: 'consultar_compra',
    mensagem: 'Não encontrei um cliente com o ID informado. Verifique o código do cliente e tente novamente.',
    compras: []
  }
}];
